using System.Security.Claims;using System.Text.Json;using HealthTracker.Api.Contracts;using HealthTracker.Api.Data;using HealthTracker.Api.Models;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Microsoft.EntityFrameworkCore;namespace HealthTracker.Api.Controllers;[Authorize][ApiController][Route("api/medicines")]public class MedicinesController(AppDbContext db):ControllerBase{Guid U=>Guid.Parse(User.FindFirstValue(ClaimTypes.NameIdentifier)!);async Task<Patient>P(Guid? patientId=null){if(patientId is null)return await db.Patients.SingleAsync(x=>x.UserId==U);var ids=await db.FamilyMembers.Where(x=>x.UserId==U&&x.Status=="approved").Join(db.FamilyMembers,a=>a.FamilyId,b=>b.FamilyId,(a,b)=>b.UserId).Distinct().ToListAsync();if(!ids.Contains(U))ids.Add(U);return await db.Patients.SingleAsync(x=>x.Id==patientId&&ids.Contains(x.UserId));}static MedicineResponse Map(Medicine m)=>new(m.Id,m.Name,m.Strength,m.Form,m.Condition,m.FrequencyPattern,JsonSerializer.Deserialize<List<string>>(m.SpecificDaysJson)??[],m.CycleEvery,m.CycleUnit,JsonSerializer.Deserialize<List<string>>(m.TimesJson)??[],m.Liquid,m.WithFood,m.StartDate.ToString("yyyy-MM-dd"),m.DurationType,m.DurationValue,m.DurationUnit,m.SupplyCount,m.RefillThreshold);[HttpGet]public async Task<IActionResult>Get([FromQuery]Guid? patientId){var p=await P(patientId);return Ok((await db.Medicines.Where(x=>x.PatientId==p.Id).ToListAsync()).Select(Map));}[HttpPost]public async Task<IActionResult>Post(MedicineRequest r,[FromQuery]Guid? patientId){var p=await P(patientId);var m=From(r,p.Id);db.Medicines.Add(m);await db.SaveChangesAsync();return Ok(Map(m));}[HttpPut("{id:guid}")]public async Task<IActionResult>Put(Guid id,MedicineRequest r,[FromQuery]Guid? patientId){var p=await P(patientId);var m=await db.Medicines.SingleOrDefaultAsync(x=>x.Id==id&&x.PatientId==p.Id);if(m is null)return NotFound();Apply(m,r);await db.SaveChangesAsync();return Ok(Map(m));}[HttpDelete("{id:guid}")]public async Task<IActionResult>Delete(Guid id,[FromQuery]Guid? patientId){var p=await P(patientId);var m=await db.Medicines.SingleOrDefaultAsync(x=>x.Id==id&&x.PatientId==p.Id);if(m is null)return NotFound();db.Medicines.Remove(m);await db.SaveChangesAsync();return NoContent();}static Medicine From(MedicineRequest r,Guid p){var m=new Medicine{PatientId=p};Apply(m,r);return m;}static void Apply(Medicine m,MedicineRequest r){m.Name=r.Name.Trim();m.Strength=r.Strength;m.Form=r.Form;m.Condition=r.Condition;m.FrequencyPattern=r.FrequencyPattern;m.SpecificDaysJson=JsonSerializer.Serialize(r.SpecificDays);m.CycleEvery=Math.Max(1,r.CycleEvery);m.CycleUnit=r.CycleUnit;m.TimesJson=JsonSerializer.Serialize(r.Times);m.Liquid=r.Liquid;m.WithFood=r.WithFood;m.StartDate=DateOnly.Parse(r.StartDate);m.DurationType=r.DurationType;m.DurationValue=r.DurationValue;m.DurationUnit=r.DurationUnit;m.SupplyCount=Math.Max(0,r.SupplyCount);m.RefillThreshold=Math.Max(0,r.RefillThreshold);}}